    last_user = max(n for n, i, a in final["ins"] if i == "USER")
    for n, i, a in final["ins"]:
        if i in ("CMD", "ENTRYPOINT"):
            rep.check(n > last_user, f"line {n}: {i} comes before the USER instruction")

